-- 02-constraints-indexes.sql — Data-free verified Supabase schema snapshot, 2026-11-05.
ALTER TABLE audit_log ADD CONSTRAINT audit_log_action_check CHECK (((char_length(action) >= 1) AND (char_length(action) <= 100)));
ALTER TABLE audit_log ADD CONSTRAINT audit_log_details_check CHECK ((jsonb_typeof(details) = 'object'::text));
ALTER TABLE audit_log ADD CONSTRAINT audit_log_pkey PRIMARY KEY (id);
ALTER TABLE idea_comments ADD CONSTRAINT comments_content_limit CHECK ((char_length(content) <= 2000));
ALTER TABLE idea_status_history ADD CONSTRAINT history_reason_limit CHECK ((char_length(COALESCE(reason, ''::text)) <= 2000));
ALTER TABLE idea_comments ADD CONSTRAINT idea_comments_content_check CHECK ((length(TRIM(BOTH FROM content)) > 0));
ALTER TABLE idea_comments ADD CONSTRAINT idea_comments_pkey PRIMARY KEY (id);
ALTER TABLE idea_followers ADD CONSTRAINT idea_followers_pkey PRIMARY KEY (id);
ALTER TABLE idea_owner_history ADD CONSTRAINT idea_owner_history_pkey PRIMARY KEY (id);
ALTER TABLE idea_private_details ADD CONSTRAINT idea_private_details_pkey PRIMARY KEY (idea_id);
ALTER TABLE idea_progress_updates ADD CONSTRAINT idea_progress_updates_pkey PRIMARY KEY (id);
ALTER TABLE idea_progress_updates ADD CONSTRAINT idea_progress_updates_update_text_check CHECK ((length(TRIM(BOTH FROM update_text)) > 0));
ALTER TABLE idea_status_history ADD CONSTRAINT idea_status_history_pkey PRIMARY KEY (id);
ALTER TABLE idea_votes ADD CONSTRAINT idea_votes_pkey PRIMARY KEY (id);
ALTER TABLE ideas ADD CONSTRAINT ideas_category_check CHECK ((((status = 'Draft'::text) AND (category = ''::text)) OR (category = ANY (ARRAY['New Service Offering'::text, 'Internal Tool'::text, 'Process Improvement'::text, 'Marketing/Content'::text, 'Client Experience'::text, 'Training'::text]))));
ALTER TABLE ideas ADD CONSTRAINT ideas_effort_score_check CHECK (((effort_score >= 1) AND (effort_score <= 5)));
ALTER TABLE ideas ADD CONSTRAINT ideas_form_limits CHECK (((char_length(problem) <= 5000) AND (char_length(proposed_solution) <= 5000) AND (char_length(who_benefits) <= 5000) AND (char_length(expected_impact) <= 5000) AND (char_length(COALESCE(outcome_summary, ''::text)) <= 2000) AND (char_length(COALESCE(demo_video_url, ''::text)) <= 2000)));
ALTER TABLE ideas ADD CONSTRAINT ideas_impact_score_check CHECK (((impact_score >= 1) AND (impact_score <= 5)));
ALTER TABLE ideas ADD CONSTRAINT ideas_pkey PRIMARY KEY (id);
ALTER TABLE ideas ADD CONSTRAINT ideas_required_on_submit CHECK (((status = 'Draft'::text) OR ((length(TRIM(BOTH FROM title)) > 0) AND (length(TRIM(BOTH FROM category)) > 0) AND (length(TRIM(BOTH FROM problem)) > 0) AND (length(TRIM(BOTH FROM proposed_solution)) > 0) AND (length(TRIM(BOTH FROM who_benefits)) > 0) AND (length(TRIM(BOTH FROM expected_impact)) > 0))));
ALTER TABLE ideas ADD CONSTRAINT ideas_rough_effort_check CHECK ((rough_effort = ANY (ARRAY['Small'::text, 'Medium'::text, 'Large'::text])));
ALTER TABLE ideas ADD CONSTRAINT ideas_status_check CHECK ((status = ANY (ARRAY['Draft'::text, 'Submitted'::text, 'Needs More Info'::text, 'Under Evaluation'::text, 'Approved'::text, 'In Progress'::text, 'Done'::text, 'Rejected'::text, 'Parked'::text, 'Withdrawn'::text])));
ALTER TABLE idea_followers ADD CONSTRAINT one_follow_per_user_per_idea UNIQUE (idea_id, user_id);
ALTER TABLE idea_votes ADD CONSTRAINT one_vote_per_user_per_idea UNIQUE (idea_id, user_id);
ALTER TABLE profiles ADD CONSTRAINT profiles_email_length CHECK (((email IS NULL) OR (char_length(email) <= 320)));
ALTER TABLE profiles ADD CONSTRAINT profiles_name_limit CHECK ((char_length(full_name) <= 100));
ALTER TABLE profiles ADD CONSTRAINT profiles_pkey PRIMARY KEY (id);
ALTER TABLE idea_progress_updates ADD CONSTRAINT progress_text_limit CHECK ((char_length(update_text) <= 2000));
ALTER TABLE audit_log ADD CONSTRAINT audit_log_actor_id_fkey FOREIGN KEY (actor_id) REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE idea_comments ADD CONSTRAINT idea_comments_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_comments ADD CONSTRAINT idea_comments_parent_comment_id_fkey FOREIGN KEY (parent_comment_id) REFERENCES idea_comments(id) ON DELETE CASCADE;
ALTER TABLE idea_comments ADD CONSTRAINT idea_comments_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE idea_followers ADD CONSTRAINT idea_followers_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_followers ADD CONSTRAINT idea_followers_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE idea_owner_history ADD CONSTRAINT idea_owner_history_assigned_by_fkey FOREIGN KEY (assigned_by) REFERENCES profiles(id);
ALTER TABLE idea_owner_history ADD CONSTRAINT idea_owner_history_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_owner_history ADD CONSTRAINT idea_owner_history_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES profiles(id);
ALTER TABLE idea_private_details ADD CONSTRAINT idea_private_details_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_private_details ADD CONSTRAINT idea_private_details_submitter_id_fkey FOREIGN KEY (submitter_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE idea_progress_updates ADD CONSTRAINT idea_progress_updates_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_progress_updates ADD CONSTRAINT idea_progress_updates_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id);
ALTER TABLE idea_status_history ADD CONSTRAINT idea_status_history_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES profiles(id);
ALTER TABLE idea_status_history ADD CONSTRAINT idea_status_history_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_votes ADD CONSTRAINT idea_votes_idea_id_fkey FOREIGN KEY (idea_id) REFERENCES ideas(id) ON DELETE CASCADE;
ALTER TABLE idea_votes ADD CONSTRAINT idea_votes_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE ideas ADD CONSTRAINT ideas_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX idea_comments_user_idx ON public.idea_comments USING btree (user_id);
CREATE INDEX idea_comments_parent_idx ON public.idea_comments USING btree (parent_comment_id);
CREATE INDEX idea_comments_idea_time_idx ON public.idea_comments USING btree (idea_id, created_at);
CREATE UNIQUE INDEX idea_followers_idea_user_unique ON public.idea_followers USING btree (idea_id, user_id);
CREATE INDEX idea_followers_user_idx ON public.idea_followers USING btree (user_id);
CREATE INDEX idea_votes_user_idx ON public.idea_votes USING btree (user_id);
