CREATE INDEX audit_log_idea_time_idx ON public.audit_log USING btree (idea_id, occurred_at DESC);
CREATE INDEX audit_log_time_idx ON public.audit_log USING btree (occurred_at DESC);
CREATE INDEX idx_ideas_owner ON public.ideas USING btree (owner_id);
CREATE INDEX idx_ideas_target_date ON public.ideas USING btree (target_date);
CREATE INDEX idx_ideas_quadrant ON public.ideas USING btree (evaluation_quadrant);
CREATE INDEX ideas_status_submitted_idx ON public.ideas USING btree (status, submitted_at, id);
CREATE INDEX ideas_category_idx ON public.ideas USING btree (category);
CREATE INDEX ideas_created_idx ON public.ideas USING btree (created_at DESC, id);
CREATE INDEX ideas_updated_idx ON public.ideas USING btree (updated_at DESC, id);
CREATE INDEX ideas_text_search_idx ON public.ideas USING gin (((((((((((COALESCE(title, ''::character varying))::text || ' '::text) || COALESCE(problem, ''::text)) || ' '::text) || COALESCE(proposed_solution, ''::text)) || ' '::text) || COALESCE(who_benefits, ''::text)) || ' '::text) || COALESCE(expected_impact, ''::text))) gin_trgm_ops);
CREATE INDEX idea_progress_user_idx ON public.idea_progress_updates USING btree (user_id);
CREATE INDEX idx_progress_updates_idea ON public.idea_progress_updates USING btree (idea_id, created_at);
CREATE INDEX profiles_name_id_idx ON public.profiles USING btree (full_name, id);
